import sys
import numpy as np
M=998244353
def factor(x):
    r={};d=2
    while d*d<=x:
        while x%d==0:
            r[d]=r.get(d,0)+1; x//=d
        d+=1
    if x>1: r[x]=r.get(x,0)+1
    return r
def solve(N,A):
    fac=[factor(a) for a in A]
    primes=set()
    for f in fac: primes|=set(f)
    ans=1
    for p in primes:
        es=[f.get(p,0) for f in fac]
        tot=sum(es); L=tot+1
        pw=np.ones(L,dtype=np.int64)
        for k in range(1,L): pw[k]=pw[k-1]*p%M
        dp=np.zeros(L,dtype=np.int64); dp[0]=1
        i=1
        for e in es:
            if e==0:
                new=dp*pw%M
            else:
                new=np.zeros(L,dtype=np.int64)
                if e<L:
                    new[e:L]=(new[e:L]+dp[0:L-e]*pw[e:L]%M)%M
                if L-e>0:
                    new[0:L-e]=(new[0:L-e]+dp[e:L]*pw[0:L-e]%M)%M
                for d in range(min(e,L)):
                    v=int(dp[d])
                    if v:
                        new[0]=(int(new[0])+v*pow(p,i*(e-d),M))%M
            dp=new; i+=1
        ans=ans*(int(dp.sum()%M))%M
    return ans
def main():
    data=sys.stdin.read().split()
    N=int(data[0])
    A=[int(x) for x in data[1:N]]
    print(solve(N,A))
main()

