import sys, heapq
def solve(boxes, M):
    if M==1:
        return sum(max(0,v-p) for v,p in boxes)
    bs=sorted(boxes,key=lambda x:-x[0])
    N=len(bs)
    if M-1>N: return 0
    k=M-2
    suf=[0]*(N+1)
    for i in range(N-1,-1,-1):
        suf[i]=suf[i+1]+max(0,bs[i][0]-bs[i][1])
    best=0
    h=[]; s=0
    for p in range(N):
        if len(h)==k:
            cand=s+(1-bs[p][1])+suf[p+1]
            if cand>best: best=cand
        a=1-bs[p][1]
        if k>0:
            heapq.heappush(h,a); s+=a
            if len(h)>k:
                s-=heapq.heappop(h)
    return best
