import heapq, sys
def solve(raw, TH=48):
    data = raw.split()
    N = int(data[0]); M = int(data[1]); Q = int(data[2])
    s = [0]*M; e = [0]*M; t = [0]*M
    p = 3
    for i in range(M):
        S = int(data[p]); T = int(data[p+1]); p += 2
        if S < T:
            s[i] = S-1; e[i] = T-1; t[i] = 1
        else:
            s[i] = T-1; e[i] = S-1; t[i] = 0
    size = 1
    while size < N: size *= 2
    SH = 18; MASK = (1 << SH) - 1; K = N + 5
    st = {'on': False}
    HA = [{}, {}]; HB = [{}, {}]
    cL = [0]*N; cR = [0]*N
    hpush = heapq.heappush; hpop = heapq.heappop
    def tree_add(j):
        tt = t[j]
        l = s[j]+1+size; r_ = e[j]+size
        kA = (e[j] << SH) | j
        kB = ((K - s[j]) << SH) | j
        HAt = HA[tt]; HBt = HB[tt]
        while l < r_:
            if l & 1:
                h = HAt.get(l)
                if h is None: HAt[l] = [kA]
                else: hpush(h, kA)
                h = HBt.get(l)
                if h is None: HBt[l] = [kB]
                else: hpush(h, kB)
                l += 1
            if r_ & 1:
                r_ -= 1
                h = HAt.get(r_)
                if h is None: HAt[r_] = [kA]
                else: hpush(h, kA)
                h = HBt.get(r_)
                if h is None: HBt[r_] = [kB]
                else: hpush(h, kB)
            l >>= 1; r_ >>= 1
    def qmin(H, pt, L):
        best = None
        node = pt + size
        while node:
            h = H.get(node)
            if h:
                while h and (h[0] & MASK) < L: hpop(h)
                if h and (best is None or h[0] < best): best = h[0]
            node >>= 1
        return best
    nxt = [M]*M
    L = 0; r = 0
    def can(j):
        sj = s[j]; ej = e[j]
        if cL[sj] or cR[ej]: return False
        tt = t[j]
        if st['on']:
            ka = qmin(HA[tt], sj, L)
            if ka is not None and (ka >> SH) < ej: return False
            kb = qmin(HB[tt], ej, L)
            if kb is not None and K - (kb >> SH) > sj: return False
            return True
        for i in range(L, r):
            if t[i] == tt:
                si = s[i]; ei = e[i]
                if (si < sj < ei < ej) or (sj < si < ej < ei): return False
        return True
    for L in range(M):
        while r < M and can(r):
            j = r
            cL[s[j]] += 1; cR[e[j]] += 1
            if st['on']:
                tree_add(j)
            elif (r - L) + 1 > TH:
                st['on'] = True
                for i in range(L, r): tree_add(i)
                tree_add(j)
            r += 1
        nxt[L] = r
        cL[s[L]] -= 1; cR[e[L]] -= 1
        if st['on'] and (r - L - 1) < TH // 2:
            st['on'] = False
            HA[0] = {}; HA[1] = {}; HB[0] = {}; HB[1] = {}
    out = []
    p = 3 + 2*M
    for _ in range(Q):
        LL = int(data[p]); RR = int(data[p+1]); p += 2
        out.append("Yes" if RR <= nxt[LL-1] else "No")
    return "\n".join(out) + "\n"

