import sys
def solve(N, G):
    in_c=[[[] for _ in range(N)] for _ in range(26)]
    out_c=[[0]*N for _ in range(26)]
    edges=[]
    for u in range(N):
        for v in range(N):
            ch=G[u][v]
            if ch!='-':
                c=ord(ch)-97
                in_c[c][v].append(u); out_c[c][u]|=1<<v; edges.append((u,v))
    vis=[0]*N; val=[[-1]*N for _ in range(N)]
    B=2*N*N+10; buckets=[[] for _ in range(B)]
    for u in range(N):
        vis[u]|=1<<u; val[u][u]=0; buckets[0].append((u,u))
    for u,v in edges:
        if not (vis[u]>>v)&1:
            vis[u]|=1<<v; val[u][v]=1; buckets[1].append((u,v))
    for d in range(B-2):
        for (u,v) in buckets[d]:
            for c in range(26):
                ins=in_c[c][u]; om=out_c[c][v]
                if not ins or not om: continue
                for p in ins:
                    m=om&~vis[p]
                    if m:
                        vis[p]|=m
                        while m:
                            low=m&-m; q=low.bit_length()-1; m^=low
                            val[p][q]=d+2; buckets[d+2].append((p,q))
    return val
def main():
    data=sys.stdin.read().split()
    N=int(data[0]); G=data[1:1+N]
    val=solve(N,G)
    print("\n".join(" ".join(map(str,r)) for r in val))
