from typing import List
class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid); m = len(grid[0])
        dirs = [(1,1),(1,-1),(-1,-1),(-1,1)]
        def ok(L, v):
            if L == 0: return False
            return (v == 2) if (L & 1) else (v == 0)
        F = []
        for di, dj in dirs:
            Fd = [0]*(n*m)
            rows = range(n) if di == 1 else range(n-1, -1, -1)
            cols = range(m) if dj == 1 else range(m-1, -1, -1)
            for i in rows:
                gi = grid[i]
                for j in cols:
                    v = gi[j]
                    if v == 1:
                        Fd[i*m+j] = 1
                    else:
                        pi = i-di; pj = j-dj
                        if 0 <= pi < n and 0 <= pj < m:
                            L = Fd[pi*m+pj]
                            if ok(L, v):
                                Fd[i*m+j] = L+1
            F.append(Fd)
        best = max(max(f) for f in F)
        for d in range(4):
            di, dj = dirs[d]
            Td = [0]*(n*m)
            Fp_arr = F[(d+3) % 4]
            rows = range(n) if di == 1 else range(n-1, -1, -1)
            cols = range(m) if dj == 1 else range(m-1, -1, -1)
            for i in rows:
                gi = grid[i]
                for j in cols:
                    v = gi[j]
                    if v == 1: continue
                    pi = i-di; pj = j-dj
                    if 0 <= pi < n and 0 <= pj < m:
                        k = pi*m+pj
                        cand = 0
                        t = Td[k]
                        if ok(t, v): cand = t+1
                        f = Fp_arr[k]
                        if ok(f, v) and f+1 > cand: cand = f+1
                        Td[i*m+j] = cand
            best = max(best, max(Td))
        return best

