from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 2)
        for i in range(1, n + 2):
            fact[i] = fact[i - 1] * i
        used = [False] * (n + 1)
        o = (n + 1) // 2
        e = n // 2

        def f(o2, e2, last_par, r):
            if r == 0:
                return 1
            nxt = 1 - last_par
            if nxt == 1:
                if o2 == (r + 1) // 2 and e2 == r // 2:
                    return fact[o2] * fact[e2]
                return 0
            else:
                if e2 == (r + 1) // 2 and o2 == r // 2:
                    return fact[o2] * fact[e2]
                return 0

        def cnt_after(v, o_cur, e_cur, r_after):
            if v % 2 == 1:
                o2, e2 = o_cur - 1, e_cur
            else:
                o2, e2 = o_cur, e_cur - 1
            return f(o2, e2, v % 2, r_after)

        total = 0
        for v in range(1, n + 1):
            total += cnt_after(v, o, e, n - 1)
        if k > total:
            return []

        res = []
        last = None
        for i in range(n):
            r_after = n - i - 1
            chosen = None
            for v in range(1, n + 1):
                if used[v]:
                    continue
                if last is not None and v % 2 == last:
                    continue
                c = cnt_after(v, o, e, r_after)
                if k > c:
                    k -= c
                else:
                    chosen = v
                    break
            used[chosen] = True
            if chosen % 2 == 1:
                o -= 1
            else:
                e -= 1
            last = chosen % 2
            res.append(chosen)
        return res

