    def distanceSum(self, m: int, n: int, k: int) -> int:
        N = m * n
        row = n * n * sum(d * (m - d) for d in range(1, m))
        col = m * m * sum(d * (n - d) for d in range(1, n))
        c = math.comb(N - 2, k - 2) % MOD
