class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        full = (1 << k) - 1
        def rot(S, c):
            if c == 0:
                return S
            return ((S << c) | (S >> (k - c))) & full
        w = [0] * h
        for i in range(h):
            j = n - 1 - i
            if i == j:
                w[i] = pow(10, i, k) % k
            else:
                w[i] = (pow(10, i, k) + pow(10, j, k)) % k
        reach = [0] * (h + 1)
        reach[h] = 1
        for i in range(h - 1, -1, -1):
            S = 0
            nxt = reach[i + 1]
            lo = 1 if i == 0 else 0
            for d in range(lo, 10):
                S |= rot(nxt, (d * w[i]) % k)
            reach[i] = S
        digits = []
        r = 0
        for i in range(h):
            lo = 1 if i == 0 else 0
            chosen = None
            for d in range(9, lo - 1, -1):
                t = (-(r + d * w[i])) % k
                if (reach[i + 1] >> t) & 1:
                    chosen = d
                    break
            if chosen is None:
                return ""
            r = (r + chosen * w[i]) % k
            digits.append(chosen)
        s = [str(x) for x in digits]
        if n % 2 == 0:
            tail = s[::-1]
        else:
            tail = s[:-1][::-1]
        return "".join(s + tail)

