class Solution:
    def makeStringGood(self, s: str) -> int:
        INF=10**9
        n=len(s); cnt=[0]*26
        for ch in s: cnt[ord(ch)-97]+=1
        def g(f):
            dp=np.zeros(1,dtype=np.int64)
            for i in range(26):
                c=cnt[i]
                if c==0:
                    if len(dp)==1:
                        if i==25: return int(dp[0])
                        continue
                    x=np.arange(len(dp),dtype=np.int64)
                    dp=np.array([min(int((dp+np.abs(x-f)).min()), int((dp+x).min()))],dtype=np.int64)
                    continue
                Y = min(c,f) if i<25 else 0
                xs=len(dp)
                x=np.arange(xs,dtype=np.int64)
                t=c+x-f
                A=dp+t; B=dp-t
                sufE=np.full(xs+1,INF,dtype=np.int64)
                sufE[:xs]=np.minimum.accumulate(A[::-1])[::-1]
                prefE=np.full(xs+1,INF,dtype=np.int64)
                prefE[1:]=np.minimum.accumulate(B)
                ys=np.arange(Y+1,dtype=np.int64)
                idx=ys+f-c
                SA=sufE[np.clip(idx,0,xs)]
                PB=prefE[np.clip(idx-1,-1,xs-1)+1]
                used=np.minimum(SA,2*ys+PB)
                unused=int((dp+c+x).min())
                dp=np.minimum(used,unused)
            return int(dp[0])
        M=max(cnt)
        best=n; done=set(); cands=[]
        for k in range(1,27):
            for f in (n//k, n//k+1, n//k-1):
                if 1<=f<=M: cands.append(f)
        for f in cands:
            if f not in done:
                done.add(f); best=min(best,g(f))
        lbs=[]
        for f in range(1,M+1):
            if f in done: continue
            lb=min(abs(n-k*f) for k in range(0,27))
            if lb<best: lbs.append((lb,f))
        lbs.sort()
        for lb,f in lbs:
            if lb>=best: break
            best=min(best,g(f))
        return best

