import re
class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        A, B, C = p.split('*')
        def occ(X):
            return [m.start() for m in re.finditer('(?=' + re.escape(X) + ')', s)]
        INF = float('inf')
        def nxt(X):
            arr = [INF] * (n + 2)
            for x in occ(X):
                arr[x] = x
            for i in range(n, -1, -1):
                if arr[i + 1] < arr[i]:
                    arr[i] = arr[i + 1]
            return arr
        nb = nxt(B)
        nc = nxt(C)
        la, lb, lc = len(A), len(B), len(C)
        best = INF
        for i in occ(A):
            k = nb[i + la] if i + la <= n else INF
            if k == INF:
                continue
            q = k + lb
            if q > n:
                continue
            m = nc[q]
            if m == INF:
                continue
            best = min(best, m + lc - i)
        return -1 if best == INF else best

