from collections import deque
def solve(data):
    n,m=data[0],data[1]
    adj=[[] for _ in range(n+1)]
    idx=2
    for _ in range(m):
        x=data[idx];y=data[idx+1];z=data[idx+2];idx+=3
        adj[x].append((y,z)); adj[y].append((x,z))
    pot=[-1]*(n+1)
    A=[0]*(n+1)
    for s in range(1,n+1):
        if pot[s]!=-1: continue
        pot[s]=0
        comp=[s]
        dq=deque([s])
        while dq:
            u=dq.popleft()
            pu=pot[u]
            for v,z in adj[u]:
                if pot[v]==-1:
                    pot[v]=pu^z; comp.append(v); dq.append(v)
                elif pot[v]!=pu^z:
                    return None
        size=len(comp)
        pots=[pot[v] for v in comp]
        r=0
        for b in range(31):
            c1=sum(1 for p in pots if p>>b&1)
            if c1*2>size:
                r|=1<<b
        for v in comp:
            A[v]=r^pot[v]
    return A[1:]
