import sys
import numpy as np

def solve(data):
    N, W = data[0], data[1]
    groups = {}
    idx = 2
    for _ in range(N):
        w, v = data[idx], data[idx+1]; idx += 2
        cnt = W // w
        if cnt == 0:
            continue
        k = np.arange(1, cnt+1, dtype=np.int64)
        g = v - (2*k - 1)
        g = g[g > 0]
        if g.size:
            groups.setdefault(w, []).append(g)
    dp = np.zeros(W+1, dtype=np.int64)
    for w, lst in groups.items():
        arr = np.concatenate(lst)
        M = W // w
        if arr.size > M:
            arr = np.partition(arr, arr.size - M)[arr.size - M:]
        arr = np.sort(arr)[::-1]
        for g in arr.tolist():
            if g <= 0:
                break
            cand = dp[:W+1-w] + g
            dp[w:] = np.maximum(dp[w:], cand)
    return int(dp[W])

def main():
    data = list(map(int, sys.stdin.read().split()))
    print(solve(data))

if __name__ == "__main__":
    main()

