import random, sys
def solve(K, S, T):
    n, m = len(S), len(T)
    if abs(n - m) > K: return "No"
    M = (1 << 61) - 1
    B = random.randrange(10**5, 10**9)
    def build(s):
        h = [0] * (len(s) + 1)
        x = 0
        for i, c in enumerate(s):
            x = (x * B + ord(c)) % M
            h[i + 1] = x
        return h
    hs, ht = build(S), build(T)
    pw = [1] * (max(n, m) + 1)
    for i in range(1, len(pw)):
        pw[i] = pw[i - 1] * B % M
    def lcp(i, j):
        mx = min(n - i, m - j)
        lo, hi = 0, mx
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if (hs[i + mid] - hs[i] * pw[mid]) % M == (ht[j + mid] - ht[j] * pw[mid]) % M:
                lo = mid
            else:
                hi = mid - 1
        return lo
    NEG = -10**9
    prev = {}
    for e in range(K + 1):
        cur = {}
        for d in range(-e, e + 1):
            if e == 0:
                i = 0
            else:
                c = NEG
                if d in prev and prev[d] > NEG: c = max(c, prev[d] + 1)
                if d - 1 in prev and prev[d - 1] > NEG: c = max(c, prev[d - 1])
                if d + 1 in prev and prev[d + 1] > NEG: c = max(c, prev[d + 1] + 1)
                if c == NEG: continue
                i = c
            i = min(i, n, m - d)
            if i < 0 or i + d < 0:
                continue
            i += lcp(i, i + d)
            cur[d] = i
            if d == m - n and i >= n:
                return "Yes"
        prev = cur
    return "No"

