import heapq
class Solution:
    def minOperations(self, n: int, m: int) -> int:
        N = 10000
        sieve = [True]*N
        sieve[0] = sieve[1] = False
        for i in range(2, int(N**0.5)+1):
            if sieve[i]:
                for j in range(i*i, N, i):
                    sieve[j] = False
        if sieve[n] or sieve[m]:
            return -1
        L = len(str(n))
        def enc(d):
            v = 0
            for x in d:
                v = v*10 + x
            return v
        start = [int(c) for c in str(n).zfill(L)]
        target = enc([int(c) for c in str(m).zfill(L)])
        INF = float('inf')
        dist = {n: n}
        pq = [(n, n, tuple(start))]
        while pq:
            d, v, digs = heapq.heappop(pq)
            if dist.get(v, INF) < d:
                continue
            if v == target:
                return d
            for i in range(L):
                for delta in (1, -1):
                    nd = digs[i] + delta
                    if 0 <= nd <= 9:
                        nd_digs = digs[:i] + (nd,) + digs[i+1:]
                        u = enc(nd_digs)
                        if sieve[u]:
                            continue
                        nd_cost = d + u
                        if nd_cost < dist.get(u, INF):
                            dist[u] = nd_cost
                            heapq.heappush(pq, (nd_cost, u, nd_digs))
        return -1

