class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        import numpy as np
        n, m = len(source), len(pattern)
        NEG = -10**9
        tgt = [False]*n
        for t in targetIndices: tgt[t] = True
        pos = {}
        for j in range(1, m+1):
            pos.setdefault(pattern[j-1], []).append(j)
        pos = {c: np.array(v, dtype=np.int64) for c, v in pos.items()}
        f = np.full(m+1, NEG, dtype=np.int64); f[0] = 0
        for i in range(n):
            new = f + 1 if tgt[i] else f.copy()
            idx = pos.get(source[i])
            if idx is not None:
                new[idx] = np.maximum(new[idx], f[idx-1])
            new[new < NEG//2] = NEG
            f = new
        return int(max(0, f[m]))

