from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        radj = [[] for _ in range(n)]
        for a, b, w in edges:
            radj[b].append((a, w))
        INF = float('inf')
        dist = [INF] * n
        dist[0] = 0
        h = [(0, 0)]
        while h:
            d, u = heapq.heappop(h)
            if d > dist[u]:
                continue
            for v, w in radj[u]:
                nd = d if d > w else w
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(h, (nd, v))
        m = max(dist)
        return -1 if m == INF else m

