import random, itertools
def fast(original, bounds):
    L=-10**19;R=10**19;b=original[0]
    for i in range(len(original)):
        d=original[i]-b;u,v=bounds[i];L=max(L,u-d);R=min(R,v-d)
    return max(0,R-L+1)
def brute(original,bounds):
    n=len(original);cnt=0
    rng=[range(u,v+1) for u,v in bounds]
    for c in itertools.product(*rng):
        if all(c[i]-c[i-1]==original[i]-original[i-1] for i in range(1,n)): cnt+=1
    return cnt
